/** Our contract and token addresses on the active chain (generated by `pnpm codegen`). */
import { arenaAddress, tradeLogAddress } from '@starter/shared/generated'
import { tokenOn } from '@starter/shared/tokens'
import type { Address } from 'viem'

export type Contracts = { tradeLog: Address; arena: Address; usdc: Address; weth?: Address }

export function contractsOn(chainId: number): Contracts {
  const pick = (map: Partial<Record<number, Address>>, name: string) => {
    const address = map[chainId]
    if (!address)
      throw new Error(`${name} is not deployed on chain ${chainId}; deploy and run pnpm codegen`)
    return address
  }
  const usdc = tokenOn(chainId, 'USDC')?.address
  if (!usdc) throw new Error(`No USDC address for chain ${chainId}`)
  return {
    tradeLog: pick(tradeLogAddress, 'TradeLog'),
    arena: pick(arenaAddress, 'Arena'),
    usdc,
    weth: tokenOn(chainId, 'WETH')?.address,
  }
}
